    // ================================================================ 心情 / 尺度 / 模式
    function MoodCard({ snap, saveConfig, notify }) {
      const config = (snap && snap.config) || {}
      const [mood, setMood] = React.useState(null)
      const [busy, setBusy] = React.useState('')
      const say = (k, t) => { if (notify) notify(k, t) }

      const load = React.useCallback(async () => {
        try {
          const r = await apiGet('/mood')
          if (r && r.ok) setMood(r.mood)
        } catch (e) {}
      }, [])
      React.useEffect(() => { load() }, [load])

      const bump = async (deltas, reason) => {
        setBusy('bump')
        try {
          const r = await apiPost('/mood/adjust', { deltas, reason })
          if (r && r.ok) { setMood(r.mood); say('ok', '心情变了') } else say('err', (r && r.error) || '失败')
        } catch (e) { say('err', String(e && e.message)) } finally { setBusy('') }
      }

      const dims = (mood && mood.dims) || []
      const composite = (mood && mood.composite) || ''
      const spice = Number(config.spiceLevel != null ? config.spiceLevel : 3)
      const SPICE_LABEL = ['克制', '暧昧', '敢开', '老司机']
      const mode = String(config.chatMode || 'daily')

      const bar = (d) => {
        const pct = Math.round((d.value || 0) * 100)
        const hot = d.delta > 0.12
        const cold = d.delta < -0.12
        return h('div', { key: d.key, style: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 } }, [
          h('span', { key: 'l', style: { width: 44, fontSize: 11.5, color: C.sub } }, d.label),
          h('div', { key: 'b', style: { flex: 1, height: 6, borderRadius: 3, background: 'rgba(255,255,255,.08)', overflow: 'hidden' } },
            h('div', { style: { width: pct + '%', height: '100%', borderRadius: 3, background: hot ? '#f56c6c' : cold ? '#5b8ff9' : 'rgba(255,255,255,.35)' } })),
          h('span', { key: 'v', style: { width: 40, textAlign: 'right', fontSize: 11, color: C.weak } }, pct + '%'),
        ])
      }

      return h(Card, {
        title: '心情 · 尺度 · 模式',
        extra: h(Pill, { tone: composite ? 'ok' : 'idle' }, composite || '平静'),
      }, [
        h('div', { key: 'desc', style: { fontSize: 12, color: C.sub, lineHeight: 1.6 } },
          '她有七情六欲，会被你的话撩到/惹到，也会随时间平复。状态会真的影响她的语气，但她不会跟你解释自己心情不好。'),
        h('div', { key: 'bars', style: { marginTop: 10 } }, dims.slice(0, 7).map(bar)),
        h('div', { key: 'ops', style: { display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 10 } }, [
          h(Btn, { key: 'a', size: 'sm', onClick: () => bump({ love: 0.3, joy: 0.2 }, '被哄'), busy: busy === 'bump' }, '哄她一下'),
          h(Btn, { key: 'b', size: 'sm', onClick: () => bump({ anger: 0.35, disgust: 0.2 }, '被惹'), busy: busy === 'bump' }, '惹她生气'),
          h(Btn, { key: 'c', size: 'sm', onClick: () => bump({ lust: 0.3, lustDesire: 0.4, love: 0.15 }, '被撩'), busy: busy === 'bump' }, '撩她'),
          h(Btn, { key: 'd', size: 'sm', variant: 'soft', onClick: async () => {
            setBusy('reset')
            try { const r = await apiPost('/mood/reset', {}); if (r && r.ok) { setMood(r.mood); say('ok', '心情已平复') } } catch (e) {} finally { setBusy('') }
          }, busy: busy === 'reset' }, '平复'),
        ]),
        h('div', { key: 'spice', style: { marginTop: 14, paddingTop: 12, borderTop: '1px solid ' + C.lineSoft } }, [
          h('div', { key: 't', style: { fontSize: 12.5, marginBottom: 6 } }, '尺度：' + SPICE_LABEL[Math.max(0, Math.min(3, spice))]),
          h('input', {
            key: 'r', type: 'range', min: 0, max: 3, step: 1, defaultValue: spice,
            style: { width: '100%' },
            onMouseUp: async (e) => {
              const v = Number(e.target.value) || 0
              const r = await saveConfig({ spiceLevel: v })
              if (r && r.ok) say('ok', '尺度已设为「' + SPICE_LABEL[v] + '」')
            },
            onTouchEnd: async (e) => {
              const v = Number(e.target.value) || 0
              const r = await saveConfig({ spiceLevel: v })
              if (r && r.ok) say('ok', '尺度已设为「' + SPICE_LABEL[v] + '」')
            },
          }),
          h('div', { key: 'h', style: { fontSize: 11, color: C.weak, marginTop: 4 } }, '0 克制 · 1 暧昧 · 2 敢开 · 3 老司机（动不动就上高速）'),
        ]),
        h('div', { key: 'mode', style: { marginTop: 12, display: 'flex', gap: 8, alignItems: 'center' } }, [
          h('span', { key: 'l', style: { fontSize: 12.5, flex: 1 } }, '模式：' + (mode === 'work' ? '工作（完整 Agent）' : '日常（纯聊天）')),
          h(Btn, { key: 's', size: 'sm', variant: mode === 'daily' ? 'primary' : 'soft', onClick: async () => { const r = await saveConfig({ chatMode: 'daily' }); if (r && r.ok) say('ok', '切换到日常模式') } }, '日常'),
          h(Btn, { key: 'w', size: 'sm', variant: mode === 'work' ? 'primary' : 'soft', onClick: async () => { const r = await saveConfig({ chatMode: 'work' }); if (r && r.ok) say('ok', '切换到工作模式') } }, '工作'),
        ]),
      ])
    }

